<?php
require __DIR__ . '/app/bootstrap.php';
$page = (string) ($_GET['page'] ?? 'home');
$allowed = ['home', 'doctors', 'login', 'register', 'appointments', 'book', 'favourites', 'profile', 'dashboard'];
if (!in_array($page, $allowed, true)) { http_response_code(404); $page = 'not_found'; }
$error = null; $databaseError = false;
try {
    if ($_SERVER['REQUEST_METHOD'] === 'POST') { handle_action(); }
} catch (mysqli_sql_exception $exception) {
    error_log($exception->getMessage());
    $error = $exception->getCode() === 1062 ? 'That username or email is already in use.' : 'The database is unavailable or needs setup. Start MySQL and import database/online_medical_protal.sql.';
} catch (RuntimeException $exception) { $error = $exception->getMessage(); }
$user = account();
if (in_array($page, ['appointments', 'book', 'favourites', 'profile', 'dashboard'], true) && !$user) { flash('Please sign in to continue.'); redirect('login'); }
if ($user && in_array($page, ['book', 'favourites'], true) && $user['role'] !== 'user') { redirect('dashboard'); }
if ($user && $page === 'dashboard' && $user['role'] === 'user') { redirect('appointments'); }
$doctors = []; $appointments = []; $saved = []; $specialities = []; $locations = []; $doctor = null; $editing = null; $profile = null; $stats = [];
try {
    if (in_array($page, ['home', 'doctors', 'favourites', 'dashboard'], true)) {
        $specialities = rows("SELECT DISTINCT doctor_type FROM doctor WHERE doctor_type <> '' ORDER BY doctor_type");
        $locations = rows("SELECT DISTINCT location FROM doctor WHERE location <> '' ORDER BY location");
        $where = []; $params = [];
        if ($page === 'favourites') { $where[] = 'd_id IN (SELECT d_id FROM favourite WHERE p_id = ?)'; $params[] = $user['id']; }
        if ($page === 'doctors') {
            $search = trim((string) ($_GET['q'] ?? ''));
            if ($search !== '') { $where[] = '(d_name LIKE ? OR doctor_type LIKE ?)'; $params[] = '%' . $search . '%'; $params[] = '%' . $search . '%'; }
            foreach (['speciality' => 'doctor_type', 'location' => 'location'] as $field => $column) {
                if (!empty($_GET[$field])) { $where[] = "$column = ?"; $params[] = (string) $_GET[$field]; }
            }
        }
        $doctors = rows('SELECT * FROM doctor' . ($where ? ' WHERE ' . implode(' AND ', $where) : '') . ' ORDER BY d_name' . ($page === 'home' ? ' LIMIT 3' : ''), $params);
        if ($user && $user['role'] === 'user') { $saved = array_column(rows('SELECT d_id FROM favourite WHERE p_id = ?', [$user['id']]), 'd_id'); }
    }
    if (in_array($page, ['appointments', 'dashboard'], true)) {
        $condition = ''; $params = [];
        if ($user['role'] === 'user') { $condition = ' WHERE a.p_id = ?'; $params[] = $user['id']; }
        elseif ($user['role'] === 'doctor') { $condition = ' WHERE a.d_id = ?'; $params[] = $user['id']; }
        $appointments = rows('SELECT a.*, d.d_name, d.doctor_type, d.price_per_appointment FROM appointment a LEFT JOIN doctor d ON d.d_id = a.d_id' . $condition . ' ORDER BY a.date DESC, a.a_id DESC', $params);
        $stats['upcoming'] = count(array_filter($appointments, function ($a) { return $a['date'] >= date('Y-m-d'); }));
        if ($user['role'] === 'admin') { $stats['patients'] = first('SELECT COUNT(*) AS total FROM users')['total']; $stats['doctors'] = count($doctors); }
    }
    if ($page === 'book') {
        $doctor = first('SELECT * FROM doctor WHERE d_id = ?', [(int) ($_GET['doctor'] ?? 0)]);
        if (!empty($_GET['edit'])) {
            $editing = first('SELECT * FROM appointment WHERE a_id = ? AND p_id = ? AND date >= ?', [(int) $_GET['edit'], $user['id'], date('Y-m-d')]);
            if ($editing) { $doctor = first('SELECT * FROM doctor WHERE d_id = ?', [(int) $editing['d_id']]); }
            else { $doctor = null; }
        }
        $profile = first('SELECT * FROM users WHERE p_id = ?', [$user['id']]);
    }
    if ($page === 'profile') {
        $map = ['user' => ['users', 'p_id'], 'doctor' => ['doctor', 'd_id'], 'admin' => ['admin', 'a_id']]; [$table, $key] = $map[$user['role']];
        $profile = first("SELECT * FROM `$table` WHERE `$key` = ?", [$user['id']]);
    }
} catch (mysqli_sql_exception $exception) { error_log($exception->getMessage()); $databaseError = true; $error = 'We cannot load your data. Please start MySQL and check the database setup.'; }
$flash = $_SESSION['flash'] ?? null; unset($_SESSION['flash']);
$titles = ['home' => 'Your health, a little simpler.', 'doctors' => 'Find your doctor', 'favourites' => 'Your favourite doctors', 'appointments' => 'Your appointments', 'dashboard' => 'Care dashboard', 'profile' => 'Your profile', 'book' => 'Book an appointment', 'login' => 'Welcome back', 'register' => 'Start your care journey', 'not_found' => 'Page not found'];
function field(string $label, string $name, string $type = 'text', string $value = '', bool $required = true): void {
    $value = $type === 'password' ? '' : (string) ($_POST[$name] ?? $value);
    echo '<label>' . e($label) . '<input type="' . e($type) . '" name="' . e($name) . '" value="' . e($value) . '" ' . ($required ? 'required' : '') . ($type === 'password' ? ' minlength="8" maxlength="72" autocomplete="new-password"' : '') . '></label>';
}
function doctor_card(array $d, array $saved, ?array $user, string $page): void { ?>
<article class="doctor-card"><div class="doctor-top"><div class="avatar" aria-hidden="true"><?= e(substr($d['d_name'], 0, 1)) ?></div><span class="tag"><?= e($d['doctor_type'] ?: 'Medical practitioner') ?></span></div>
<h3><?= e($d['d_name']) ?></h3><p class="muted"><?= e($d['location'] ?: 'Location not listed') ?></p><p class="doctor-description"><?= e($d['description'] ?: 'View this doctor and choose an appointment session that works for you.') ?></p>
<div class="fee"><span>Consultation fee</span><strong>LKR <?= number_format((float) $d['price_per_appointment'], 2) ?></strong></div>
<div class="card-actions"><a class="button small" href="<?= e(url('book', ['doctor' => $d['d_id']])) ?>">Book appointment <span aria-hidden="true">↗</span></a>
<?php if ($user && $user['role'] === 'user'): $isSaved = in_array($d['d_id'], $saved); ?><form method="post"><?= csrf() ?><input type="hidden" name="action" value="favourite"><input type="hidden" name="doctor_id" value="<?= (int) $d['d_id'] ?>"><input type="hidden" name="return_page" value="<?= e($page) ?>"><button class="save-button <?= $isSaved ? 'saved' : '' ?>" aria-label="<?= $isSaved ? 'Remove from' : 'Add to' ?> favourites" aria-pressed="<?= $isSaved ? 'true' : 'false' ?>"><?= $isSaved ? '♥' : '♡' ?></button></form><?php endif ?></div></article>
<?php }
