<?php if ($page === 'home'): ?>
<section class="hero container"><div class="hero-copy"><p class="eyebrow"><span class="dot"></span> YOUR CARE, CONNECTED</p><h1>Your health,<br>a little <em>simpler.</em></h1><p class="intro">Find the right doctor. Make time for your health. Keep your appointments together, all in one place.</p><div class="hero-actions"><a class="button" href="<?= e(url('doctors')) ?>">Find a doctor <span aria-hidden="true">↗</span></a><a class="text-link" href="<?= e(url($user ? 'appointments' : 'login')) ?>">Manage my appointments →</a></div><div class="hero-note"><span class="mini-icon" aria-hidden="true">✚</span><p>Care that fits your day.<br><span>Search, book and manage online.</span></p></div></div><div class="hero-visual"><img src="<?= e(app_base()) ?>/images/girldoc.jpg" alt="Medical professional at the hospital"><div class="image-label"><span class="status-circle" aria-hidden="true">✓</span><div><strong>A healthier tomorrow</strong><span>Starts with a little care today.</span></div></div><span class="visual-caption">APPOLO MEDICAL / PATIENT CARE</span></div></section>
