<section class="container section"><div class="section-heading"><div><p class="eyebrow">FIND YOUR NEXT STEP</p><h2>Good care starts with the right doctor.</h2></div><a class="text-link" href="<?= e(url('doctors')) ?>">View all doctors ↗</a></div><div class="doctor-grid"><?php foreach ($doctors as $d) { doctor_card($d, $saved, $user, $page); } ?></div><?php if (!$doctors && !$databaseError): ?><div class="empty"><span aria-hidden="true">✚</span><h3>Our doctor directory is getting ready.</h3><p>Doctors added by your administrator will appear here.</p></div><?php endif ?></section>
