<section class="container section"><p class="eyebrow">YOUR CARE TEAM</p><h1 class="page-title"><?= e($titles[$page]) ?></h1><p class="intro"><?= $page === 'favourites' ? 'The doctors you saved, ready when you need them.' : 'Find a specialist and choose your next appointment.' ?></p>
<?php if ($page === 'doctors'): ?><form class="search-form panel" method="get"><input type="hidden" name="page" value="doctors"><label>Doctor or speciality<input name="q" placeholder="Search by name or speciality" value="<?= e($_GET['q'] ?? '') ?>"></label><label>Speciality<select name="speciality"><option value="">All specialities</option><?php foreach ($specialities as $s): ?><option <?= ($_GET['speciality'] ?? '') === $s['doctor_type'] ? 'selected' : '' ?>><?= e($s['doctor_type']) ?></option><?php endforeach ?></select></label><label>Location<select name="location"><option value="">All locations</option><?php foreach ($locations as $l): ?><option <?= ($_GET['location'] ?? '') === $l['location'] ? 'selected' : '' ?>><?= e($l['location']) ?></option><?php endforeach ?></select></label><button class="button">Search ↗</button><a class="text-link" href="<?= e(url('doctors')) ?>">Clear</a></form><?php endif ?>
